---说明按钮点击回调
function OverseaStoreLimitedTimeSkinNode:BtnExplainOnClickHandler()
    local data = self:GetProductData()
    local skinId = data.rewards[1].goodsId
    local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(skinId)
    local roleId = skinVo.roleId
    local cardRoleVo = CardConfMgr:GetInstance():GetCardByRefId(roleId)
    local numText = ''
    local nameText = ''
    if checkInt(data.price) > 0 then
        numText = CfUtils.GetCustomDisplayPrice(data.discountPrice, data.channelProductId)
    else
        local prices = checkTable(data.prices)
        local goodsId = prices[1].currency 
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        numText = data.discountPrice
        nameText = goodsVo.name
    end
    local discount = string.format('-%s%%', checkInt(tonumber(data.iconTitle) * 100))
    local tips = localize("获取战斗员——_name1_后可享有<color=#E71F55>_num1_</color>优惠，仅需<color=#E71F55>_num2__name2_</color>即可购买该时装。", {_name1_ = cardRoleVo.name, _num1_ = discount, _num2_ = numText, _name2_ = nameText})
    GameUtils.SecondConfirm(tips, function()
        local gachaponUtils = import('Game.Gachapon.GachaponUtils')
        gachaponUtils.OpenGachapon(nil, { { id = Constants.UITypeIds.OverseaStore } })
    end, nil, localize("(您还未拥有该皮肤对应战斗员)"), 12, nil, nil, nil, nil, nil, nil, nil, true)
end

---购买按钮点击回调
function OverseaStoreLimitedTimeSkinNode:BtnDirectPurchaseOnClickHandler()
    local data = self:GetProductData()
    local skinId = data.rewards[1].goodsId
    local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(skinId)
    local roleId = skinVo.roleId
    local cardComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
    local isHave = cardComp:IsHasCard(roleId)
    if isHave then
        if checkInt(data.price) > 0 then
            local payPoint = isNotNull(data.price) and data.price or data.payPoint
            SDKService:GetInstance():PayMoney({
                productId = data.productId,
                channelProductId = data.channelProductId,
                productDesc = skinVo.name,
                payAmount = checkNumber(payPoint),
                data = data
            })
        else
            local consume = clone(data.prices)
            for _, v in pairs(consume) do
                v.goodsId = v.currency
                v.num = v.current
            end
            local _, errTip = GoodsUtils.CheckGoodConsume(consume)
            if errTip then
                if consume[1].goodsId == Constants.Currency.PayDiamondId then
                    local productVo = GoodsConfMgr:GetInstance():GetGoodsVoById(consume[1].goodsId)
                    ServerDifferenceMgr:WrapPrimaryCurrencyBuy({currency = consume[1].goodsId,current = consume[1].num, productName = productVo.name})
                else
                    GameUtils.Toast(errTip)
                end
            else
                local prices = checkTable(data.prices)
                local goodsId = prices[1].currency
                local goodsNum = prices[1].current
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                local tips = localize('是否花费<color=#E71F55>_num1__name1_</color>购买该时装？', {_num1_ = goodsNum, _name1_ = goodsVo.name})
                GameUtils.SecondConfirm(tips, function()
                    GameUtils.Request(Interfaces.StoreLimitedTimeSkinBuy, {productId = data.productId, num = 1, currency = goodsId}, Bind(self, self.SkinBuyResponseHandler))
                end)
            end
        end
        return
    end
    local cardRoleVo = CardConfMgr:GetInstance():GetCardByRefId(roleId)
    local priceText = nil
    if checkInt(data.price) > 0 then
        priceText = CfUtils.GetCustomDisplayPrice(data.discountPrice, data.channelProductId)
    else
        local prices = checkTable(data.prices)
        local goodsId = prices[1].currency
        local goodsNum = data.discountPrice
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        priceText = goodsNum .. goodsVo.name
    end
    local discount = string.format('-%s%%', checkInt(tonumber(data.iconTitle) * 100))
    local tips = localize("获取战斗员——_name_后可享有<color=#E71F55>_num1_</color>优惠，仅需<color=#E71F55>_num2_</color>即可购买该时装。", {_name_ = cardRoleVo.name, _num1_ = discount, _num2_ = priceText})
    GameUtils.SecondConfirm(tips, function()
        local gachaponUtils = import('Game.Gachapon.GachaponUtils')
        gachaponUtils.OpenGachapon(nil, { { id = Constants.UITypeIds.OverseaStore } })
    end, function()
        if checkInt(data.price) > 0 then
            local payPoint = isNotNull(data.price) and data.price or data.payPoint
            SDKService:GetInstance():PayMoney({
                productId = data.productId,
                channelProductId = data.channelProductId,
                productDesc = skinVo.name,
                payAmount = checkNumber(payPoint),
                data = data
            })
        else
            local prices = checkTable(data.prices)
            local goodsId = prices[1].currency
            GameUtils.Request(Interfaces.StoreLimitedTimeSkinBuy, {productId = data.productId, num = 1, currency = goodsId}, Bind(self, self.SkinBuyResponseHandler))
        end
    end, localize("(您还未拥有该皮肤对应战斗员)"), 13, data , nil, nil, nil, nil, nil, nil, true)
end

