---最终奖励领取response处理
function OverseaStoreLimitedTimeSkinNode:FinalRewardsResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end
    
    if response.data.rewards then
        GoodsUtils.DrawRewards(response.data.rewards, true)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = response.data.rewards}})
    end
    
    OverseaStoreMgr:SetLimitedTimeSkinFinalReceived(1)
    self:RefreshRewards()
    self:RefreshPrice()
end

---购买response处理
function OverseaStoreLimitedTimeSkinNode:SkinBuyResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end

    if response.data.rewards then
        local data = self:GetProductData()
        local prices = checkTable(data.prices)
        local goodsId = prices[1].currency
        local goodsNum = prices[1].current
        local consume = {{goodsId = goodsId, num = -goodsNum, productId = checkNumber(data.productId)}}
        GoodsUtils.DrawRewards(consume, true)
        
        GoodsUtils.DrawRewards(response.data.rewards, true)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = response.data.rewards}})
    end
    
    self:RefreshUI()
end
--endregion handler

