    self:RefreshTab()
end

---刷新页签
function OverseaStoreLimitedTimeSkinNode:RefreshTab()
    local products = self:GetProducts()
    for i, v in ipairs(products) do
        local btnTab = self["BtnTag" .. i]
        local selectNode = btnTab:Find("StatusSelect")
        CfUtils.SetActive(selectNode, i == self:GetSelectedIndex())
        
        local imageNode = btnTab:Find("ImgTag")
        local productData = self:GetProducts()[i]
        local skinId = productData.rewards[1].goodsId
        local imagePath = CfUtils.GetImageFullPath(productData.showImage)
        CfUtils.FillImage(imageNode, imagePath)
        
        local finishNode = btnTab:Find("Finish")
        local cardSkinComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardSkinComponent)
        CfUtils.SetActive(finishNode, cardSkinComponent:IsHasSkin(skinId))

        local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(skinId)
        local textName = btnTab:Find("Name/TextDesc")
        CfUtils.FillText(textName, skinVo.name)
    end
    self:RefreshVideo()
    self:RefreshRewards()
    self:RefreshPrice()
end

---刷新视频
function OverseaStoreLimitedTimeSkinNode:RefreshVideo()
    local data = self:GetProductData()

    -- 版权
    if isNotNull(data.specialLogo) then
        CfUtils.SetActive(self.ImgCopyright, true)
        local path = CfUtils.GetImageFullPath(data.specialLogo)
        CfUtils.FillImage(self.ImgCopyright, path)
    else
        CfUtils.SetActive(self.ImgCopyright, false)
    end
    
    local path = string.format('Movie/%s.usm', data.showVideo)
    Events.Broadcast(Constants.EventNames.OVERSEA_STORE_PLAY_VIDEO, path)
end

---刷新收集奖
function OverseaStoreLimitedTimeSkinNode:RefreshRewards()
    local products = self:GetProducts()
    local cardSkinComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardSkinComponent)
    local progress = 0
    for i, v in ipairs(products) do
        local productData = self:GetProducts()[i]
        local skinId = productData.rewards[1].goodsId
        if cardSkinComponent:IsHasSkin(skinId) then
            progress = progress + 1
        end
    end

    local storeData = self:GetStoreData()
    local finalRewards = storeData.finalRewards
    local finalReceived = checkInt(storeData.finalReceived)
    local goodsId = finalRewards[1].goodsId
    local env = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, "Game.Behaviours.CommonPlayerHeadNode")
    if env then
        env:FreshFrame(goodsId, true)
        env:SetCallBack(function()
            if progress >= #products then
                if finalReceived == 0 then
                    GameUtils.Request(Interfaces.StoreLimitedTimeSkinReceive, nil, Bind(self, self.FinalRewardsResponseHandler))
                end
            else
                GameUtils.ShowCommonGoodsTipsBoard(self.CommonPlayerHeadNode, goodsId)
            end
        end)
    end
    
    if progress >= #products then
        CfUtils.SetActive(self.Progress, false)
        if finalReceived >= 1 then
            CfUtils.SetActive(self.CanReceive, false)
            CfUtils.SetActive(self.Finish, true)
        else
            CfUtils.SetActive(self.CanReceive, true)
            CfUtils.SetActive(self.Finish, false)
        end
    else
        CfUtils.SetActive(self.Progress, true)
        CfUtils.FillText(self.HeadFrameTextNumber, string.format("%d/%d", progress, #products))
    end
end

---刷新价格
function OverseaStoreLimitedTimeSkinNode:RefreshPrice()
    local data = self:GetProductData()
    local skinId = data.rewards[1].goodsId
    local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(skinId)
    local roleId = skinVo.roleId

    ---@type CardSkinComponent
    local cardSkinComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardSkinComponent)
    local hasSkin = cardSkinComponent:IsHasSkin(skinId)
    if hasSkin then
        CfUtils.SetActive(self.BtnDirectPurchase, false)
        CfUtils.SetActive(self.FontStyleButton, true)
        CfUtils.SetActive(self.UIFX_DiscountedPrice_Button, false)
        CfUtils.SetActive(self.Discount, false)
        CfUtils.SetActive(self.DiscountLink, false)
        return 
    else
        CfUtils.SetActive(self.BtnDirectPurchase, true)
        CfUtils.SetActive(self.FontStyleButton, false)
        CfUtils.SetActive(self.Discount, true)
    end
    
    ---@type CardComponent
    local cardComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
    local isHave = cardComp:IsHasCard(roleId)
    if checkInt(data.price) > 0 then
        -- 直充
        CfUtils.FillText(self.PriceTextNumber, CfUtils.GetCustomDisplayPrice(data.windowsPriceId, data.channelProductId, 30))
        CfUtils.SetActive(self.PriceImgIcon, false)
        if isHave then
            CfUtils.SetActive(self.OriginalPrice, true)
            CfUtils.SetActive(self.OriginalPriceImgIcon, false)
            
        else
            CfUtils.SetActive(self.OriginalPrice, false)
        end
    else
        -- 道具
        local prices = checkTable(data.prices)
        local goodsId = prices[1].currency
        local goodsNum = prices[1].current
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        CfUtils.SetActive(self.PriceImgIcon, true)
        CfUtils.FillImage(self.PriceImgIcon, goodsVo.photoPath)
        CfUtils.FillText(self.PriceTextNumber, goodsNum)
        if isHave then
            CfUtils.SetActive(self.OriginalPrice, true)
        else
            CfUtils.SetActive(self.OriginalPrice, false)
        end
    end
    if isHave then
        CfUtils.SetActive(self.DiscountLink, false)
        CfUtils.SetActive(self.DiscountUnlock, true)
        CfUtils.SetActive(self.DiscountLock, false)
        CfUtils.SetActive(self.UIFX_DiscountedPrice_Button, true)
        CfUtils.FillText(self.DiscountUnlockTxtNumber, string.format('-%s%%', checkInt(tonumber(data.iconTitle) * 100)))
        
    else
        CfUtils.SetActive(self.DiscountLink, true)
        CfUtils.SetActive(self.DiscountUnlock, false)
        CfUtils.SetActive(self.DiscountLock, true)
        CfUtils.SetActive(self.UIFX_DiscountedPrice_Button, false)
        CfUtils.FillText(self.DiscountLockTxtNumber, string.format('-%s%%', checkInt(tonumber(data.iconTitle) * 100)))
        CfUtils.FillText(self.DiscountLinkTextDesc, localize("获取战斗员享受折扣价格"))
    end
end
